def isNumeral(e: Expr): Boolean = getType(e) match {
  case Some(t) => Formula.isTrue(analyzer.equivalent(t, Types.INT_LITERAL)) ||
                  Formula.isTrue(analyzer.equivalent(t, Types.FLOAT_LITERAL))
  case None => false
