        Site s = ((Numeral) v).site();
        for (FGenericFunction g : Coercions.numeralCoercions(target, s.radixPoint)) {
            if (!whereHolds(g.getFnDecl(), numbers(g.getFnDecl(), s, false))) continue;
            synchronized (s) {
                if (!s.converted.containsKey(target)) {
